**Pattern applied:**
```typescript
.withHandler((state, event) => {
  // Immediate optimistic update
  const menuItem = menuItemAdapter.selectById(state.menuItems, event.payload.id);
  if (!menuItem) return state;

  const optimisticMenuItem = new MenuItem({
    ...menuItem,
    proposedChange: null,
    proposalStatus: "None",
    updatedAt: event.payload.updatedAt,
  });

  return state.update({...});
})
.withSideEffects(({ event, prevState }) =>
  Effect.gen(function* () {
    // Snapshot from prevState (before optimistic update)
    const snapshot = createSnapshot(prevState.menuItems.entities[event.payload.id]);
    const client = yield* MenuItemRpcClient;

    // RPC with rollback on error
    return yield* Effect.gen(function* () {
      const result = yield* client.Method(event.payload);
      return [/* success events */];
    }).pipe(
      Effect.tapError(Effect.logError),
      Effect.tapDefect(Effect.logFatal),
      Effect.match({
        onFailure: (error) => handleOptimisticUpdateError({
          error, snapshot,
          createRollbackEvent: (menuItem) => new SystemUpdatedMenuItem({
            updated: menuItem,
            origin: null,
          }),
          createFinishedEvent: () => new SystemFinishedPendingAction(),
          logContext: "EventName",
        }),
        onSuccess: (events) => events,
      }),
    );
  })
)
```

**Type check:** ✅ Clean (all errors are pre-existing in store-builder tests, same as Recipe implementation)

**Note:** MenuItem doesn't have separate Delete or Deactivate events like Recipe. Those operations are handled through the `UserSubmittedMenuItemCreateRevision` event with the `deleteOrActivateStatus` parameter.

